import{_ as r,l,o as e,c as s,v as t,p as d,x as o,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"JWT 陷阱","description":"","frontmatter":{"title":"JWT 陷阱","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/jwt-pitfalls.md","filePath":"cs/jwt-pitfalls.md","lastUpdated":1789023840000}'),h={name:"cs/jwt-pitfalls.md"};function u(A,a,E,_,f,T){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="jwt-陷阱" tabindex="-1">JWT 陷阱 <a class="header-anchor" href="#jwt-陷阱" aria-label="Permalink to &quot;JWT 陷阱&quot;">​</a></h1><div class="epigraph"><p>JWT 把声明做成可验的紧凑串。陷阱是算法可切换成 none、用对称密钥去验非对称、不验 aud/exp，于是「有令牌」再次变成装饰。</p><footer>—— RFC 7519；RFC 7515 JWS；Jones、Bradley 与 Sakimura；对照 auth0/jwt 误用报告一类公开分析</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/arp-spoofing">ARP</a>结束信道映射。身份课序从<strong>应用令牌</strong>起。主干会话可能已有 cookie；JWT 常被当成无状态银弹。缺口是声明合同与算法混淆，不给伪造步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>alg=none</code>、把公钥当 HMAC 密钥、不检查 <code>iss</code>/<code>aud</code>、过长有效期、把权限写进不可吊销的胖令牌。缺口是验证库的默认值，不是 JSON 语法。</p><h3 id="签名-加密" tabindex="-1">签名≠加密 <a class="header-anchor" href="#签名-加密" aria-label="Permalink to &quot;签名≠加密&quot;">​</a></h3><p>JWS 可验不可隐藏。敏感声明要 JWE 或根本不要放进去。</p><p><span class="marginnote">RFC 7519。本课禁止构造恶意 JWT 的操作指导。密钥轮换与 <code>kid</code> 注入是实现问题：只接受已知 kid。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列出必须检查的头与声明。对照服务端会话：可吊销、可短。JWT 适合短命访问令牌，刷新走服务端。下一课会话管理把 cookie 旗标收全。</p>',12)),(e(),d(p,null,{default:o(()=>[c(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOK%5B%22JWT%22%5D%20--%3E%20ALG%5B%22%E9%92%89%E6%AD%BB%E5%85%81%E8%AE%B8%E7%AE%97%E6%B3%95%22%5D%0A%20%20TOK%20--%3E%20SIG%5B%22%E7%94%A8%E6%AD%A3%E7%A1%AE%E5%AF%86%E9%92%A5%E9%AA%8C%E7%AD%BE%22%5D%0A%20%20SIG%20--%3E%20CLAIM%5B%22iss%20aud%20exp%20nbf%22%5D%0A%20%20CLAIM%20--%3E%20OK%5B%22%E6%8E%A5%E5%8F%97%E5%A3%B0%E6%98%8E%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无状态的代价是吊销难。证明在「验签+声明」游戏内；<code>none</code> 与错钥是游戏外。OAuth 后课会发这种令牌——先把验法钉死。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 JOSE 算法套件。会话管理下一课：cookie、CSRF、固定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>信道映射之后，应用身份常是 JWT。</li><li>钉算法、验签、验 aud/exp；JWS 不保密。</li><li>胖令牌难吊销；宜短命。</li><li>下一课会话管理。</li><li>出处：RFC 7519；RFC 7515；对照 OWASP 对 JWT 的讨论（机制，非利用手册）。</li></ul>',8))])}const J=r(h,[["render",u]]);export{S as __pageData,J as default};
